"""Original IELTS-format Listening parts.

Every script is written for this project (not copied from any publisher) and
follows the four-part IELTS structure: an everyday conversation, an everyday
monologue, an academic discussion and an academic lecture. Each line names a
voice role so the client can render distinct speakers with text-to-speech.
"""

N, F, M, F2, M2 = "narrator", "female", "male", "female2", "male2"


def line(voice: str, speaker: str, text: str) -> dict:
    return {"voice": voice, "speaker": speaker, "text": text}


